B.z8=new A.cO([1,"B\u1ea1n \u0111\xe3 l\xe2u ch\u01b0a \u0111\u1ed3ng b\u1ed9 d\u1eef li\u1ec7u r\u1ed3i. \u0110\u1ed3ng b\u1ed9 m\u1ed9t ch\xfat \u0111\u1ec3 l\u1ecbch h\u1ecdc v\xe0 l\u1ecbch thi lu\xf4n ch\xednh x\xe1c nh\xe9.",2,"\u0110\u1ed3ng b\u1ed9 xong r\u1ed3i. Hi\u1ec7n ch\u01b0a c\xf3 thay \u0111\u1ed5i m\u1edbi trong l\u1ecbch c\u1ee7a b\u1ea1n.",3,"L\u1ecbch h\u1ecdc c\u1ee7a b\u1ea1n v\u1eeba c\xf3 thay \u0111\u1ed5i. Ki\u1ec3m tra l\u1ea1i \u0111\u1ec3 tr\xe1nh nh\u1ea7m l\u1ecbch nh\xe9.",4,"L\u1ecbch thi c\u1ee7a b\u1ea1n v\u1eeba c\xf3 thay \u0111\u1ed5i. Ki\u1ec3m tra l\u1ea1i \u0111\u1ec3 tr\xe1nh nh\u1ea7m l\u1ecbch nh\xe9.",5,"L\u1ecbch h\u1ecdc v\xe0 l\u1ecbch thi c\u1ee7a b\u1ea1n v\u1eeba c\xf3 thay \u0111\u1ed5i. B\u1ea1n ki\u1ec3m tra l\u1ea1i nh\xe9.",6,"C\xf2n 7 ng\xe0y n\u1eefa thi r\u1ed3i. B\u1ea1n ki\u1ec3m tra l\u1ecbch nh\xe9.",7,"C\xf2n 3 ng\xe0y n\u1eefa thi r\u1ed3i. B\u1ea1n ki\u1ec3m tra l\u1ecbch nh\xe9.",8,"Ng\xe0y mai thi r\u1ed3i. B\u1ea1n ki\u1ec3m tra l\u1ea1i l\u1ecbch nh\xe9.",9,"C\xf2n X ng\xe0y n\u1eefa thi. B\u1ea1n ki\u1ec3m tra l\u1ecbch nh\xe9.",10,"B\u1ea1n \u0111ang trong k\u1ef3 thi. Nh\u1edb ki\u1ec3m tra l\u1ecbch thi nh\xe9.",11,"C\xf2n X ng\xe0y n\u1eefa b\u1ea1n c\xf3 N m\xf4n thi. Ki\u1ec3m tra l\u1ecbch nh\xe9.",12,"\u0110\u1ed3ng b\u1ed9 xong r\u1ed3i. L\u1ecbch c\u1ee7a b\u1ea1n c\xf3 thay \u0111\u1ed5i.",13,"\u0110\u1ed3ng b\u1ed9 xong r\u1ed3i. L\u1ecbch c\u1ee7a b\u1ea1n v\u1eabn nh\u01b0 c\u0169.",14,"L\u1ecbch c\u1ee7a b\u1ea1n c\xf3 thay \u0111\u1ed5i. M\u1edf chi ti\u1ebft \u0111\u1ec3 ki\u1ec3m tra nh\xe9.",15,"Hi\u1ec7n t\u1ea1i b\u1ea1n ch\u01b0a c\xf3 l\u1ecbch thi.",16,"H\xf4m nay kh\xf4ng c\xf3 l\u1ecbch h\u1ecdc.",17,"\u0110\u1ed3ng b\u1ed9 ch\u01b0a th\xe0nh c\xf4ng. B\u1ea1n th\u1eed l\u1ea1i nh\xe9.",18,"\u0110\u1ed3ng b\u1ed9 m\u1ea5t qu\xe1 l\xe2u. B\u1ea1n th\u1eed l\u1ea1i sau nh\xe9."],t.TM)
