B.XT=new A.cO([1,"\u0110\xe3 v\u01b0\u1ee3t qu\xe1 kho\u1ea3ng th\u1eddi gian khuy\u1ebfn ngh\u1ecb gi\u1eefa hai l\u1ea7n \u0111\u1ed3ng b\u1ed9. T\xf4i \u0111\u1ec1 ngh\u1ecb b\u1ea1n c\u1eadp nh\u1eadt d\u1eef li\u1ec7u \u0111\u1ec3 gi\u1ea3m nguy c\u01a1 sai l\u1ec7ch so v\u1edbi h\u1ec7 th\u1ed1ng QL\u0110T.",2,"Qu\xe1 tr\xecnh \u0111\u1ed3ng b\u1ed9 \u0111\xe3 ho\xe0n t\u1ea5t. D\u1eef li\u1ec7u hi\u1ec7n t\u1ea1i kh\xf4ng c\xf3 sai kh\xe1c so v\u1edbi l\u1ea7n \u0111\u1ed3ng b\u1ed9 th\xe0nh c\xf4ng g\u1ea7n nh\u1ea5t.",3,"Ph\xe1t hi\u1ec7n sai kh\xe1c trong d\u1eef li\u1ec7u l\u1ecbch h\u1ecdc so v\u1edbi l\u1ea7n \u0111\u1ed3ng b\u1ed9 g\u1ea7n nh\u1ea5t. Vui l\xf2ng ki\u1ec3m tra chi ti\u1ebft thay \u0111\u1ed5i.",4,"Ph\xe1t hi\u1ec7n sai kh\xe1c trong d\u1eef li\u1ec7u l\u1ecbch thi so v\u1edbi l\u1ea7n \u0111\u1ed3ng b\u1ed9 g\u1ea7n nh\u1ea5t. Vui l\xf2ng ki\u1ec3m tra chi ti\u1ebft thay \u0111\u1ed5i.",5,"Ph\xe1t hi\u1ec7n sai kh\xe1c \u0111\u1ed3ng th\u1eddi trong d\u1eef li\u1ec7u l\u1ecbch h\u1ecdc v\xe0 l\u1ecbch thi so v\u1edbi l\u1ea7n \u0111\u1ed3ng b\u1ed9 g\u1ea7n nh\u1ea5t. Vui l\xf2ng ki\u1ec3m tra chi ti\u1ebft c\xe1c thay \u0111\u1ed5i.",6,"K\u1ef3 thi c\xf2n 7 ng\xe0y. H\xe3y r\xe0 so\xe1t l\u1ecbch thi.",7,"K\u1ef3 thi c\xf2n 3 ng\xe0y. H\xe3y r\xe0 so\xe1t l\u1ecbch v\xe0 chu\u1ea9n b\u1ecb.",8,"K\u1ef3 thi di\u1ec5n ra v\xe0o ng\xe0y mai. H\xe3y r\xe0 so\xe1t l\u1ecbch thi.",9,"K\u1ef3 thi c\xf2n X ng\xe0y. H\xe3y ki\u1ec3m tra l\u1ecbch v\xe0 \u0111i\u1ec1u ch\u1ec9nh k\u1ebf ho\u1ea1ch \xf4n t\u1eadp.",10,"B\u1ea1n \u0111ang trong giai \u0111o\u1ea1n thi. H\xe3y th\u01b0\u1eddng xuy\xean r\xe0 so\xe1t l\u1ecbch thi.",11,"Trong X ng\xe0y t\u1edbi c\xf3 N m\xf4n thi. H\xe3y ph\xe2n b\u1ed5 th\u1eddi gian \xf4n t\u1eadp ph\xf9 h\u1ee3p.",12,"\u0110\u1ed3ng b\u1ed9 ho\xe0n t\u1ea5t v\xe0 ph\xe1t hi\u1ec7n sai kh\xe1c so v\u1edbi d\u1eef li\u1ec7u tr\u01b0\u1edbc \u0111\xf3.",13,"\u0110\u1ed3ng b\u1ed9 ho\xe0n t\u1ea5t. Kh\xf4ng ph\xe1t hi\u1ec7n sai kh\xe1c so v\u1edbi d\u1eef li\u1ec7u tr\u01b0\u1edbc \u0111\xf3.",14,"Ph\xe1t hi\u1ec7n sai kh\xe1c trong d\u1eef li\u1ec7u. Vui l\xf2ng ki\u1ec3m tra ph\u1ea7n chi ti\u1ebft.",15,"D\u1eef li\u1ec7u hi\u1ec7n t\u1ea1i ch\u01b0a ghi nh\u1eadn ca thi n\xe0o.",16,"D\u1eef li\u1ec7u hi\u1ec7n t\u1ea1i kh\xf4ng ghi nh\u1eadn bu\u1ed5i h\u1ecdc n\xe0o trong h\xf4m nay.",17,"Qu\xe1 tr\xecnh \u0111\u1ed3ng b\u1ed9 kh\xf4ng ho\xe0n t\u1ea5t. Vui l\xf2ng th\u1ef1c hi\u1ec7n l\u1ea1i \u0111\u1ec3 c\u1eadp nh\u1eadt d\u1eef li\u1ec7u.",18,"Y\xeau c\u1ea7u \u0111\u1ed3ng b\u1ed9 \u0111\xe3 v\u01b0\u1ee3t ng\u01b0\u1ee1ng th\u1eddi gian ch\u1edd. Vui l\xf2ng th\u1ef1c hi\u1ec7n l\u1ea1i."],t.TM)
B.XO=new A.cO([1,"C\xf3 m\u1ed7i c\xe1i vi\u1ec7c sync m\xe0 m\xe0y c\u0169ng l\u01b0\u1eddi? Mai \u0111i h\u1ecdc mu\u1ed9n \u0111\u1eebng \u0111\u1ed5 t\u1ea1i tao nh\xe9.",2,"Tao sync xong r\u1ed3i \u0111\u1ea5y, m\xe0y ch\u1ea3 \u0111\u01b0\u1ee3c ngh\u1ec9 bu\u1ed5i n\xe0o.",3,"L\u1ecbch h\u1ecdc \u0111\u1ed5i r\u1ed3i \u0111\u1ea5y, c\xf2n kh\xf4ng mau check \u0111i?",4,"L\u1ecbch thi \u0111\u1ed5i r\u1ed3i \u0111\u1ea5y. Kh\xf4ng check th\xec tr\u01b0\u1ee3t r\xe1ng ch\u1ecbu.",5,"M\xe0y l\xe0m g\xec m\xe0 ng\u01b0\u1eddi ta \u0111\u1ed5i c\u1ea3 l\u1ecbch h\u1ecdc l\u1eabn l\u1ecbch thi c\u1ee7a m\xe0y r\u1ed3i k\xeca.",6,"7 ng\xe0y n\u1eefa thi r\u1ed3i m\xe0 m\xe0y ch\u01b0a ch\u1ecbu h\u1ecdc \xe0?",7,"3 ng\xe0y n\u1eefa thi m\xe0 gi\u1edd v\u1eabn ng\u1ed3i l\u01b0\u1edbt?",8,"N\xf3i kh\xf4ng nghe!? Mai thi gi\u1edd l\u1ea1i c\u1eafm \u0111\u1ea7u \xf4n.",9,"C\xf2n X ng\xe0y n\u1eefa thi, gi\u1edd m\u1edbi nh\u1edb t\u1edbi \xe0?",10,"\u0110ang trong k\u1ef3 thi \u0111\u1ea5y, qu\xean l\u1ecbch th\xec t\u1ef1 \u0111i m\xe0 g\xe1nh.",11,"C\xf2n X ng\xe0y n\u1eefa m\xe0y c\xf3 N m\xf4n thi \u0111\u1ea5y, ch\u01a1i \xedt th\xf4i!",12,"L\u1ecbch \u0111\u1ed5i r\u1ed3i \u0111\u1ea5y, v\xe0o xem \u0111i? L\u1ea1y B\u1ed1\u1ed1\u1ed1!",13,"Sync xong r\u1ed3i \u0111\u1ea5y, v\u1eabn ch\u1ea3 \u0111\u01b0\u1ee3c ngh\u1ec9.",14,"V\xe0o xem c\xf3 g\xec \u0111\u1ed5i chi ti\u1ebft k\xeca? \u0110\u1ee3i tao \u0111\u1ecdc cho nghe \xe0?",15,"Qu\u1ea9y \u0111\xea, n\xe0o c\xf3 l\u1ecbch tao b\xe1o.",16,"M\xe3i m\u1edbi \u0111\u01b0\u1ee3c ngh\u1ec9 1 h\xf4m.",17,"C\xf3 m\u1ed7i c\xe1i sync m\xe0 m\xe0y c\u0169ng l\u1ed7i? L\xe0m l\u1ea1i \u0111\xea!",18,"M\xe0y \u0111\u1ecbnh ch\u1edd bao l\xe2u n\u1eefa? Kh\xf4ng bi\u1ebft \u0111\u01b0\u1eddng m\xe0 sync l\u1ea1i \xe0?"],t.TM)
B.XS=new A.cO([1,"Ph\xe1p tr\u1eadn l\xe2u ng\xe0y ch\u01b0a \u0111\u01b0\u1ee3c v\u1eadn, truy\u1ec1n t\u1ed1ng t\u1eafc ngh\u1ebdn. Mau \u0111\u1ed3ng b\u1ed9 k\u1ebbo tu h\xe0nh g\u1eb7p sai s\xf3t.",2,"Ph\xe1p tr\u1eadn khai th\xf4ng, truy\u1ec1n t\u1ed1ng kh\xf4ng c\xf3 sai s\xf3t. Thi\xean \u0111\u1ea1o b\u1ea5t bi\u1ebfn \u2014 an t\xe2m tu h\xe0nh.",3,"Thi\xean c\u01a1 \u0111\u1ea1i bi\u1ebfn, d\u1ec5 sinh d\u1ecb t\u01b0\u1ee3ng. C\xf2n kh\xf4ng mau ki\u1ec3m tra?",4,"B\xed c\u1ea3nh m\u1edbi xu\u1ea5t hi\u1ec7n, th\xed luy\u1ec7n \u1eaft bi\u1ebfn. Mau ki\u1ec3m tra l\u1ea1i!",5,"Thi\xean c\u01a1 h\u1ed7n lo\u1ea1n, b\xed c\u1ea3nh \u0111\u1ea1i bi\u1ebfn. C\xf2n kh\xf4ng mau r\xe0 so\xe1t?",6,"7 ng\xe0y n\u1eefa, thi\xean ki\u1ebfp gi\xe1ng l\xe2m. Tr\u1eddi sinh d\u1ecb bi\u1ebfn \u2014 mau chu\u1ea9n b\u1ecb \u0111\u1ed9 ki\u1ebfp.",7,"3 ng\xe0y sau, thi\xean ki\u1ebfp \u0111\xe3 c\u1eadn k\u1ec1. L\xf4i v\xe2n t\xedch t\u1ee5 \u2014 c\xf2n kh\xf4ng mau b\u1ebf quan?",8,"Thi\xean ki\u1ebfp gi\xe1ng l\xe2m. Gi\u1eef v\u1eefng \u0111\u1ea1o t\xe2m \u2014 ch\xfac ng\u01b0\u01a1i may m\u1eafn!",9,"X ng\xe0y sau, tu vi vi\xean m\xe3n. L\xf4i ki\u1ebfp gi\xe1ng l\xe2m \u2014 h\xe3y chu\u1ea9n b\u1ecb th\u1eadt t\u1ed1t!",10,"\u0110\xe3 t\u1edbi k\u1ef3 \u0111\u1ed9 ki\u1ebfp, Thi\xean \u0111\u1ea1o kh\u1ea3o h\u1ea1ch. D\u1ecb \u0111\u1ed9ng l\u01b0u t\xe2m \u2014 \u0111\u1ea1o n\xe0y \u0111i sai, v\u1ea1n ki\u1ebfp b\u1ea5t ph\u1ee5c.",11,"C\xf2n X ng\xe0y, N \u0111\u1ea1o thi\xean ki\u1ebfp c\xf9ng l\xfac gi\xe1ng xu\u1ed1ng. Tu vi c\xf3 h\u1ea1n \u2014 ch\u1edb c\xf3 l\u01a1 l\xe0!",12,"Ph\xe1p tr\u1eadn khai th\xf4ng, truy\u1ec1n t\u1ed1ng sinh bi\u1ebfn. Thi\xean c\u01a1 ngh\u1ecbch v\u1eadn \u2014 mau ki\u1ec3m tra.",13,"Ph\xe1p tr\u1eadn v\u1eeba khai th\xf4ng, truy\u1ec1n t\u1ed1ng kh\xf4ng c\xf3 sai s\xf3t. Thi\xean \u0111\u1ea1o b\u1ea5t bi\u1ebfn \u2014 an t\xe2m tu h\xe0nh.",14,"Thi\xean c\u01a1 kh\u1ebd \u0111\u1ed9ng, b\xed c\u1ea3nh \u1eaft bi\u1ebfn. Mau m\u1edf chi ti\u1ebft ki\u1ec3m tra.",15,"B\xed c\u1ea3nh ch\u01b0a m\u1edf, ch\u1edb v\u1ed9i kh\u1ea3o h\u1ea1ch. H\xe3y chu\u1ea9n b\u1ecb th\u1eadt t\u1ed1t!",16,"Nay v\xf4 bi\u1ebfn v\xf4 m\u01b0u, an t\xe2m t\u0129nh d\u01b0\u1ee1ng.",17,"Ph\xe1p tr\u1eadn ph\u1ea3n ph\u1ec7, truy\u1ec1n t\u1ed1ng kh\xf4ng th\xe0nh. C\xf2n kh\xf4ng mau th\u1eed l\u1ea1i?",18,"Ph\xe1p tr\u1eadn \u0111\xecnh tr\u1ec7, thi\xean \u0111\u1ea1o kh\xf3 dung. Ch\u1edb c\u01b0\u1ee1ng c\u1ea7u \u2014 h\xe3y quay l\u1ea1i sau."],t.TM)
